import zipfile, struct, os, shutil

SRC = r'C:\Users\kougo\Downloads\小鹏p7安装器.apk'
DEX = r'C:\Users\kougo\Doubao\chats\2026-11-05\new-chat\小鹏p7安装器_分析\classes_patched.dex'
OUT = r'C:\Users\kougo\Doubao\chats\2026-11-05\new-chat\小鹏p7安装器_分析\unsigned.apk'

zin = zipfile.ZipFile(SRC)
# keep original order, drop signature files (they will be regenerated by the signer)
order = [i for i in zin.infolist() if not i.filename.startswith('META-INF/')]
print("entries kept:", [i.filename for i in order])

zf = zipfile.ZipFile(OUT, 'w')
for info in order:
    payload = open(DEX, 'rb').read() if info.filename == 'classes.dex' else zin.read(info.filename)
    zi = zipfile.ZipInfo(info.filename, date_time=info.date_time)
    zi.compress_type = info.compress_type
    zi.external_attr = info.external_attr
    zi.create_system = info.create_system
    extra = b''
    if info.compress_type == zipfile.ZIP_STORED:
        # align stored data start to 4 bytes by adding an android-style padding extra field
        off = zf.fp.tell()
        base = off + 30 + len(info.filename.encode()) + 4  # 4 = minimum extra field (id+len)
        pad = (-base) % 4
        extra = struct.pack('<HH', 0xD935, pad) + b'\x00' * pad
    zi.extra = extra
    zf.writestr(zi, payload)
zf.close()

print("built:", OUT, os.path.getsize(OUT), "bytes")

# verify alignment / integrity of the result
z = zipfile.ZipFile(OUT)
bad = z.testzip()
print("testzip:", bad)
for i in z.infolist():
    off = i.header_offset
    raw = open(OUT, 'rb').read()
    nlen, elen = struct.unpack_from('<HH', raw, off + 26)
    data_off = off + 30 + nlen + elen
    print(f"{i.filename:24s} method={i.compress_type} data_off={data_off} align4={data_off % 4 == 0} size={i.file_size}")
